<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Kanban Board</title>
  <style>
    :root {
      --bg: #eef1f6;
      --ink: #1c2430;
      --muted: #5b6678;
      --line: #d5dbe6;
      --todo: #4f7cff;
      --doing: #e0a106;
      --done: #1f9d6a;
      --shadow: 0 8px 24px rgba(28, 36, 48, 0.08);
    }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    html, body { height: 100%; }
    body {
      font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
      background:
        radial-gradient(1200px 500px at 10% -10%, #dce7ff 0%, transparent 55%),
        radial-gradient(900px 400px at 100% 0%, #d9f3e7 0%, transparent 50%),
        var(--bg);
      color: var(--ink);
      padding: 28px 24px 36px;
    }
    .app {
      max-width: 1180px;
      margin: 0 auto;
    }
    h1 {
      font-size: 28px;
      letter-spacing: -0.03em;
      margin-bottom: 6px;
    }
    .sub {
      color: var(--muted);
      font-size: 14px;
      margin-bottom: 22px;
    }
    .composer {
      display: flex;
      gap: 10px;
      margin-bottom: 22px;
      background: #fff;
      border: 1px solid var(--line);
      border-radius: 14px;
      padding: 10px;
      box-shadow: var(--shadow);
    }
    #new-card {
      flex: 1;
      border: 1px solid var(--line);
      border-radius: 10px;
      padding: 12px 14px;
      font: inherit;
      outline: none;
      background: #f8fafc;
    }
    #new-card:focus {
      border-color: #8aa8ff;
      box-shadow: 0 0 0 3px rgba(79, 124, 255, 0.18);
      background: #fff;
    }
    #add-card {
      border: 0;
      border-radius: 10px;
      padding: 0 18px;
      font: inherit;
      font-weight: 650;
      color: #fff;
      background: linear-gradient(180deg, #628aff, #3d6df5);
      cursor: pointer;
      min-width: 108px;
    }
    #add-card:hover { filter: brightness(1.05); }
    #add-card:active { transform: translateY(1px); }
    .board {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      align-items: start;
    }
    .column {
      background: rgba(255, 255, 255, 0.72);
      border: 1px solid var(--line);
      border-radius: 16px;
      min-height: 420px;
      display: flex;
      flex-direction: column;
      box-shadow: var(--shadow);
      overflow: hidden;
    }
    .column.drag-over {
      outline: 2px dashed #7b95e8;
      outline-offset: -4px;
      background: #f4f7ff;
    }
    .col-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 14px 16px 12px;
      border-bottom: 1px solid var(--line);
      background: #fff;
    }
    .col-head h2 {
      font-size: 15px;
      font-weight: 700;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .dot {
      width: 9px;
      height: 9px;
      border-radius: 50%;
      display: inline-block;
    }
    #col-todo .dot { background: var(--todo); }
    #col-doing .dot { background: var(--doing); }
    #col-done .dot { background: var(--done); }
    .count {
      min-width: 26px;
      height: 22px;
      padding: 0 7px;
      border-radius: 999px;
      background: #eef2f7;
      color: var(--muted);
      font-size: 12px;
      font-weight: 700;
      display: inline-flex;
      align-items: center;
      justify-content: center;
    }
    .cards {
      padding: 12px;
      display: flex;
      flex-direction: column;
      gap: 10px;
      flex: 1;
      min-height: 280px;
    }
    .card {
      background: #fff;
      border: 1px solid #e4e9f1;
      border-radius: 12px;
      padding: 12px 12px 12px 14px;
      box-shadow: 0 4px 12px rgba(28, 36, 48, 0.05);
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 10px;
      cursor: grab;
      user-select: none;
    }
    .card:active { cursor: grabbing; }
    .card.dragging { opacity: 0.45; }
    .card-title {
      font-size: 14px;
      line-height: 1.45;
      word-break: break-word;
      flex: 1;
    }
    .card-del {
      border: 0;
      background: #f3f5f8;
      color: #6b7382;
      width: 26px;
      height: 26px;
      border-radius: 8px;
      cursor: pointer;
      font-size: 16px;
      line-height: 1;
      flex: none;
    }
    .card-del:hover {
      background: #ffe8e8;
      color: #c62828;
    }
    @media (max-width: 860px) {
      .board { grid-template-columns: 1fr; }
      .column { min-height: 180px; }
    }
  </style>
</head>
<body>
  <div class="app">
    <h1>Kanban Board</h1>
    <p class="sub">Add cards, drag them across columns, and they stay after reload.</p>
    <div class="composer">
      <input id="new-card" type="text" placeholder="What needs doing?" autocomplete="off" />
      <button id="add-card" type="button">Add card</button>
    </div>
    <div class="board">
      <section class="column" id="col-todo">
        <header class="col-head">
          <h2><span class="dot"></span> To Do</h2>
          <span class="count">0</span>
        </header>
        <div class="cards" data-col="todo"></div>
      </section>
      <section class="column" id="col-doing">
        <header class="col-head">
          <h2><span class="dot"></span> Doing</h2>
          <span class="count">0</span>
        </header>
        <div class="cards" data-col="doing"></div>
      </section>
      <section class="column" id="col-done">
        <header class="col-head">
          <h2><span class="dot"></span> Done</h2>
          <span class="count">0</span>
        </header>
        <div class="cards" data-col="done"></div>
      </section>
    </div>
  </div>
  <script>
    (function () {
      const STORAGE_KEY = "kanban-board-state-v1";
      const COLS = ["todo", "doing", "done"];
      const colEls = {
        todo: document.getElementById("col-todo"),
        doing: document.getElementById("col-doing"),
        done: document.getElementById("col-done")
      };
      const input = document.getElementById("new-card");
      const addBtn = document.getElementById("add-card");

      let cards = load();
      let dragId = null;

      function uid() {
        return "c" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
      }

      function load() {
        try {
          const raw = localStorage.getItem(STORAGE_KEY);
          if (!raw) return [];
          const parsed = JSON.parse(raw);
          if (!Array.isArray(parsed)) return [];
          return parsed
            .filter(function (c) {
              return c && typeof c.title === "string" && COLS.indexOf(c.col) !== -1 && c.id;
            })
            .map(function (c) {
              return { id: String(c.id), title: c.title, col: c.col };
            });
        } catch (e) {
          return [];
        }
      }

      function save() {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(cards));
      }

      function updateCounts() {
        COLS.forEach(function (col) {
          var n = cards.filter(function (c) { return c.col === col; }).length;
          colEls[col].querySelector(".count").textContent = String(n);
        });
      }

      function render() {
        COLS.forEach(function (col) {
          var box = colEls[col].querySelector(".cards");
          box.innerHTML = "";
          cards.filter(function (c) { return c.col === col; }).forEach(function (c) {
            box.appendChild(makeCardEl(c));
          });
        });
        updateCounts();
      }

      function makeCardEl(card) {
        var el = document.createElement("article");
        el.className = "card";
        el.draggable = true;
        el.dataset.id = card.id;

        var title = document.createElement("div");
        title.className = "card-title";
        title.textContent = card.title;

        var del = document.createElement("button");
        del.type = "button";
        del.className = "card-del";
        del.setAttribute("aria-label", "Delete card");
        del.textContent = "×";
        del.addEventListener("click", function (e) {
          e.stopPropagation();
          cards = cards.filter(function (c) { return c.id !== card.id; });
          save();
          render();
        });

        el.addEventListener("dragstart", function (e) {
          dragId = card.id;
          el.classList.add("dragging");
          e.dataTransfer.setData("text/plain", card.id);
          e.dataTransfer.effectAllowed = "move";
        });
        el.addEventListener("dragend", function () {
          dragId = null;
          el.classList.remove("dragging");
          COLS.forEach(function (col) { colEls[col].classList.remove("drag-over"); });
        });

        el.appendChild(title);
        el.appendChild(del);
        return el;
      }

      function addCard() {
        var title = (input.value || "").trim();
        if (!title) return;
        cards.push({ id: uid(), title: title, col: "todo" });
        input.value = "";
        save();
        render();
        input.focus();
      }

      function moveCard(id, dest) {
        if (!id || COLS.indexOf(dest) === -1) return;
        var idx = -1;
        for (var i = 0; i < cards.length; i++) {
          if (cards[i].id === id) { idx = i; break; }
        }
        if (idx === -1) return;
        var item = cards[idx];
        cards.splice(idx, 1);
        item.col = dest;
        cards.push(item);
        save();
        render();
      }

      function columnKeyFromEl(el) {
        if (!el) return null;
        if (el.id === "col-todo") return "todo";
        if (el.id === "col-doing") return "doing";
        if (el.id === "col-done") return "done";
        var col = el.closest(".column");
        if (!col) return null;
        if (col.id === "col-todo") return "todo";
        if (col.id === "col-doing") return "doing";
        if (col.id === "col-done") return "done";
        return null;
      }

      COLS.forEach(function (col) {
        var column = colEls[col];
        column.addEventListener("dragover", function (e) {
          e.preventDefault();
          e.dataTransfer.dropEffect = "move";
          column.classList.add("drag-over");
        });
        column.addEventListener("dragenter", function (e) {
          e.preventDefault();
          column.classList.add("drag-over");
        });
        column.addEventListener("dragleave", function (e) {
          if (!column.contains(e.relatedTarget)) {
            column.classList.remove("drag-over");
          }
        });
        column.addEventListener("drop", function (e) {
          e.preventDefault();
          column.classList.remove("drag-over");
          var id = e.dataTransfer.getData("text/plain") || dragId;
          var dest = columnKeyFromEl(column);
          moveCard(id, dest);
        });
      });

      addBtn.addEventListener("click", addCard);
      input.addEventListener("keydown", function (e) {
        if (e.key === "Enter") addCard();
      });

      render();
    })();
  </script>
</body>
</html>
